// Generated app artwork, served only through the exact public image and manifest routes below.
// Keep these versioned URLs stable; use v2 filenames for future artwork changes.
const encoded = {
  "/app-icons/money-hq-v1-512.png": "",
  "/app-icons/money-hq-v1-180.png": "",
  "/app-icons/money-hq-v1-32.png": "",
  "/app-icons/money-hq-v1-192.png": ""
};
const images = Object.fromEntries(Object.entries(encoded).map(([url, base64]) => [url, Buffer.from(base64, 'base64')]));
const manifests = {
  "/app-icons/money-hq-v1.webmanifest": {
    "name": "Money HQ",
    "short_name": "Money HQ",
    "id": "/",
    "start_url": "/",
    "scope": "/",
    "display": "standalone",
    "background_color": "#F7F4ED",
    "theme_color": "#2F6F5E",
    "icons": [
      {
        "src": "/app-icons/money-hq-v1-192.png",
        "sizes": "192x192",
        "type": "image/png",
        "purpose": "any"
      },
      {
        "src": "/app-icons/money-hq-v1-512.png",
        "sizes": "512x512",
        "type": "image/png",
        "purpose": "any"
      }
    ]
  }
};
export function registerBrandAssets(app) {
  app.get(Object.keys(images), (req, res) => {
    res.set('Cache-Control', 'public, max-age=604800');
    res.type('image/png').send(images[req.path]);
  });
  app.get(Object.keys(manifests), (req, res) => {
    res.set('Cache-Control', 'public, max-age=300');
    res.type('application/manifest+json').send(JSON.stringify(manifests[req.path]));
  });
}
